INSERT INTO `va_manufacturers` (`id`, `name`, `slug`, `country`, `founded_year`, `description`) VALUES
(1, 'ПАО «Туполев»', 'tupolev', 'Россия', 1922, 'Легендарное советское и российское авиационное опытно-конструкторское бюро.'),
(2, 'ПАО «Ил» (Ильюшин)', 'ilyushin', 'Россия', 1933, 'Ведущий разработчик военно-транспортных и пассажирских самолётов.'),
(3, 'ПАО «Компания «Сухой»', 'sukhoi', 'Россия', 1939, 'Один из мировых лидеров в создании боевых и гражданских авиационных комплексов.'),
(4, 'The Boeing Company', 'boeing', 'США', 1916, 'Один из крупнейших мировых производителей авиационной и аэрокосмической техники.'),
(5, 'Airbus SE', 'airbus', 'Евросоюз', 1970, 'Крупнейшая европейская авиастроительная корпорация.'),
(6, 'ПАО «Яковлев» (Иркут)', 'yakovlev', 'Россия', 1934, 'Разработчик учебно-боевых самолётов Як-130 и пассажирских лайнеров МС-21, SJ-100.'),
(7, 'Cessna Aircraft Company', 'cessna', 'США', 1927, 'Мировой эталон самолётов малой авиации общего назначения.')
INSERT INTO `va_aircraft` (`id`, `manufacturer_id`, `category_code`, `slug`, `model_name`, `icao_code`, `iata_code`, `first_flight_date`, `production_years`, `wing_configuration`, `generation`, `status`, `short_desc`, `full_desc`, `history_text`, `combat_record`, `safety_record`, `hero_image`, `views_count`) VALUES
(1, 1, 'civil', 'tu-154m', 'Ту-154М', 'T154', '154', '1982-05-21', '1984–2013', 'monoplane', '2-е поколение', 'historic', 'Легендарный советский трехдвигательный реактивный среднемагистральный пассажирский лайнер.', 'Ту-154М — наиболее совершенная и экономичная модификация всемирно известного лайнера Туполева с высокоэффективными двигателями Д-30КУ-154-II. Самолет стал визитной карточкой советской и российской гражданской авиации на десятилетия.', 'Разработка модификации «М» началась в начале 1980-х годов под руководством генерального конструктора А. С. Шенгардта для радикального повышения топливной эффективности и дальности полета.', 'Использовался также государственными авиаотрядами, ВВС и в специальных правительственных перевозках.', 'Всего выпущено 1026 самолетов Ту-154 всех модификаций. На модификацию М пришлась наиболее надежная часть эксплуатации.', 'uploads/aircraft/tu154m.jpg', 1420),
