INSERT INTO `va_airlines` (`id`, `name_ru`, `name_en`, `slug`, `iata`, `icao`, `callsign`, `country`, `alliance`, `fleet_size`, `founded_year`, `hub_airport_id`, `logo_url`, `description`, `baggage_rules`) VALUES
(1, 'Аэрофлот — Российские авиалинии', 'Aeroflot - Russian Airlines', 'aeroflot', 'SU', 'AFL', 'AEROFLOT', 'Россия', 'skyteam', 170, 1923, 1, 'uploads/photos/spotting_a350.jpg', 'Национальный авиаперевозчик России, одна из старейших авиакомпаний мира.', 'Ручная кладь: 1 место до 10 кг (55x40x25 см). Багаж: Эконом — 1 место до 23 кг, Бизнес — 2 места до 32 кг.'),
(2, 'S7 Airlines (Авиакомпания «Сибирь»)', 'S7 Airlines', 's7-airlines', 'S7', 'SBI', 'SIBERIAN AIRLINES', 'Россия', 'oneworld', 102, 1957, 2, 'uploads/photos/spotting_b787.jpg', 'Крупнейшая частная авиакомпания России с яркими зелёными ливреями.', 'Ручная кладь: до 10 кг (55x40x23 см). Тарифы «Базовый» без багажа, «Гибкий» включает 1 место до 23 кг.'),
(3, 'Emirates', 'Emirates', 'emirates', 'EK', 'UAE', 'EMIRATES', 'ОАЭ', 'none', 260, 1985, 6, 'uploads/photos/spotting_tu154.jpg', 'Один из мировых лидеров дальнемагистральных авиаперевозок, крупнейший оператор A380 и Boeing 777.', 'Ручная кладь: 7 кг. Багаж по весовой системе: от 20 до 35 кг в экономе, 40 кг в бизнесе.')
INSERT INTO `va_glossary` (`term`, `abbreviation`, `category`, `short_def`, `full_explanation`, `practical_example`) VALUES
('V1 (Decision Speed)', 'V1', 'acronym', 'Скорость принятия решения на разбеге.', 'Критическая скорость разбега при взлете, до достижения которой взлет может быть безопасно прерван при отказе двигателя. После прохождения V1 взлет должен быть продолжен в любом случае.', 'Экипаж слышит команду второго пилота: «V1, Rotate!» — после чего отрыв носовой стойки неизбежен.'),
('TCAS', 'TCAS', 'systems', 'Система предупреждения столкновения самолетов в воздухе.', 'Traffic Alert and Collision Avoidance System. Автономный комплекс, опрашивающий ответчики соседних бортов и выдающий экипажу команды уклонения (Resolution Advisory: Climb / Descend).', 'TCAS Callout: «CLIMB, CLIMB NOW!» — пилот обязан немедленно выполнить указание системы, даже вопреки командам диспетчера.'),
('Глиссада (Glide Slope)', 'GS', 'navigation', 'Профильная траектория снижения самолёта при заходе на посадку.', 'Наклонная прямая линия (обычно под углом 3° к горизонту), ведущая точно к расчетной точке приземления на ВПП.', '«VladAero 102, захватил курсовой и глиссаду ВПП 24L, к посадке готов».'),
('Козление (Bounced Landing)', NULL, 'slang', 'Отделение самолёта от ВПП после первого касания.', 'Авиационный жаргонизм, обозначающий опасный отскок самолёта от полосы из-за избыточной вертикальной скорости, неправильного угла выравнивания или порыва ветра.', 'При возникновении прогрессирующего «козления» РЛЭ предписывает немедленный уход на второй круг (Go-Around).'),
('RVSM', 'RVSM', 'navigation', 'Сокращенный минимум вертикального эшелонирования.', 'Reduced Vertical Separation Minimum — стандарт полетов с интервалом 1000 футов (300 м) между эшелонами от FL290 до FL410.', 'Для допуска к RVSM борт должен иметь 2 независимых высотомера и автомат удержания высоты.')
INSERT INTO `va_quizzes` (`id`, `slug`, `title`, `description`, `category`, `difficulty`, `time_limit_sec`, `reward_xp`) VALUES
(1, 'aerodynamics-basics', 'Основы практической аэродинамики', 'Проверьте свои знания о подъёмной силе, угле атаки, срыве потока и центровке ВС.', 'Теория полета', 'cadet', 300, 150),
(2, 'aircraft-identification', 'Угадай самолет по силуэту и ТТХ', 'Сможете ли вы безошибочно отличить A350 от Dreamliner, а Су-57 от F-22?', 'Визуальное распознавание', 'ppl', 400, 200),
(3, 'metar-taf-master', 'Мастер расшифровки METAR и TAF', 'Тест на чтение сводок авиационной метеорологии в реальных условиях.', 'Метеорология', 'cpl_atpl', 450, 300)
INSERT INTO `va_quiz_questions` (`quiz_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`) VALUES
(1, 'Что происходит с подъемной силой крыла при превышении критического угла атаки (Critical AOA)?', 'Плавно увеличивается в 2 раза', 'Резко падает из-за срыва пограничного слоя (Stall)', 'Остается постоянной за счет механизации', 'Превращается в силу тяги', 'b', 'При превышении критического угла атаки поток воздуха больше не может плавно обтекать верхнюю поверхность крыла, происходит срыв струй и резкая потеря подъемной силы.'),
(1, 'Какой прибор в кабине самолета показывает скорость изменения высоты (м/с или фут/мин)?', 'Высотомер (Altimeter)', 'Авиагоризонт (Attitude Indicator)', 'Вариометр (Vertical Speed Indicator / VSI)', 'Указатель истинной скорости (TAS)', 'c', 'Вариометр (VSI) измеряет дифференциальное изменение статического давления воздуха во времени и отображает вертикальную скорость снижения или набора высоты.'),
(1, 'Что такое аэродинамическое качество крыла (Lift-to-Drag ratio)?', 'Отношение веса конструкции к весу топлива', 'Отношение коэффициента подъемной силы Cy к коэффициенту лобового сопротивления Cx', 'Максимальная скорость пикирования', 'Угол стреловидности передней кромки крыла', 'b', 'Аэродинамическое качество K = L/D показывает, сколько метров по горизонтали может пролететь самолет в режиме планирования при потере 1 метра высоты в штиль.')
