INSERT INTO `va_articles` (`id`, `author_id`, `slug`, `title`, `summary`, `content`, `blocks_json`, `cover_image`, `is_breaking`, `is_published`, `reading_time_min`) VALUES
(1, 1, 'mc-21-composite-wing-revolution', 'Революция «черного крыла»: как создавался композитный кессон МС-21', 'Детальный инженерный разбор уникальной технологии вакуумной инфузии российского среднемагистрального лайнера МС-21.', 'Самолет МС-21 стал первым в мире узкофюзеляжным пассажирским лайнером вместимостью свыше 150 мест с цельнокомпозитным крылом большого удлинения.', '[{"type":"hud_alert","title":"ИНЖЕНЕРНЫЙ ПРОРЫВ","text":"Удлинение крыла МС-21 составляет 11.5 против 9.5 у конкурентов A320neo и B737 MAX, снижая индуктивное сопротивление на 6-8%."},{"type":"specs_table","specs":{"Размах крыла":"35.9 м","Удельный расход топлива":"-12% к аналогам","Ширина фюзеляжа":"4.06 м (рекорд класса)"}},{"type":"quote","author":"Главный конструктор МС-21","text":"Мы сразу проектировали самолет под стандарты середины XXI века, сделав фюзеляж шире, а крыло совершеннее."}]', 'uploads/articles/mc21_first_flight.jpg', 1, 1, 6)
INSERT INTO `va_incidents` (`id`, `slug`, `title`, `event_date`, `flight_number`, `aircraft_type`, `airline_name`, `location_name`, `fatalities`, `survivors`, `cause_category`, `summary`, `safety_lessons`, `cover_image`) VALUES
(1, 'miracle-on-the-hudson-us-airways-1549', '«Чудо на Гудзоне»: посадка Airbus A320 на реку Гудзон', '2009-01-15', 'AWE1549', 'Airbus A320-214', 'US Airways', 'Нью-Йорк, река Гудзон', 0, 155, 'weather', 'Спустя 3 минуты после взлета из аэропорта Ла-Гуардия лайнер столкнулся со стаей канадских казарок, что вызвало отказ обоих двигателей. Капитан Чесли «Салли» Салленбергер и второй пилот Джефф Скайлз хладнокровно спланировали и приводнили борт на Гудзон.', 'Уроки безопасности: 1) Регулярные тренировки экипажей по CRM (управление ресурсами кабины) и быстрому принятию решений. 2) Доработка систем защиты аэропортов от птиц (биоакустические и радарные комплексы). 3) Внедрение в QRH коротких чек-листов двойного отказа двигателей на малой высоте.', 'uploads/aircraft/a350_900.jpg')
